// Editable image-space articulated puppet; this is not automatic anatomy recovery.
export const cutoutWalkDefaults={walkFrontShoulderX:474,walkFrontShoulderY:287,walkFrontElbowX:491,walkFrontElbowY:523,walkFrontWristX:554,walkFrontWristY:720,walkBackShoulderX:618,walkBackShoulderY:458,walkBackElbowX:704,walkBackElbowY:595,walkBackWristX:766,walkBackWristY:625,walkArmSwing:7,walkElbowSwing:4,walkWristSwing:2,walkArmsEnabled:true,walkRate:.85,walkStride:12,walkKnee:10,walkPhase:0,walkBob:3,walkEdgeThreshold:100,walkRig:{width:1024,height:1536,hip:[520,930],backKnee:[310,1160],frontKnee:[700,1170],flashlight:[850,690],parts:{body:[[0,0],[1024,0],[1024,960],[0,960]],backThigh:[[350,890],[550,940],[390,1195],[220,1160]],backShin:[[235,1120],[405,1160],[370,1475],[45,1475],[45,1320]],frontThigh:[[500,890],[740,900],[810,1200],[600,1210]],frontShin:[[600,1130],[805,1120],[860,1290],[980,1370],[965,1490],[620,1490]]}}};
const cache=new WeakMap();function parts(image,f){const key=JSON.stringify([f.walkRig,f.walkEdgeThreshold,f.walkArmsEnabled,image.src,image._assetRevision]),old=cache.get(image);if(old?.key===key)return old.parts;const rig=f.walkRig,result={};const cuts={...rig.parts};if(f.walkArmsEnabled){cuts.backArm=[[610,445],[670,490],[758,596],[845,640],[880,716],[810,730],[704,676],[610,590]];cuts.frontArm=[[436,245],[535,260],[560,460],[611,690],[627,811],[570,834],[518,775],[451,590],[410,410]];}for(const [name,poly]of Object.entries(cuts)){const canvas=Object.assign(document.createElement('canvas'),{width:rig.width,height:rig.height}),c=canvas.getContext('2d');c.beginPath();poly.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.clip();c.drawImage(image,0,0,rig.width,rig.height);const pixels=c.getImageData(0,0,rig.width,rig.height);for(let i=3;i<pixels.data.length;i+=4)if(pixels.data[i]<f.walkEdgeThreshold)pixels.data[i]=0;c.putImageData(pixels,0,0);result[name]=canvas}cache.set(image,{key,parts:result});return result;}
export function cutoutWalkPose(time,input={}){const f={...cutoutWalkDefaults,...input},p=time*f.walkRate*Math.PI*2+f.walkPhase;return {back:Math.sin(p)*f.walkStride,front:-Math.sin(p)*f.walkStride,backKnee:Math.max(0,Math.sin(p+.7))*f.walkKnee,frontKnee:Math.max(0,-Math.sin(p+.7))*f.walkKnee,arm:Math.sin(p)*f.walkArmSwing,elbow:Math.sin(p+.5)*f.walkElbowSwing,wrist:Math.sin(p+.8)*f.walkWristSwing,bob:Math.cos(p*2)*f.walkBob};}
export function paintCutoutWalk(c,image,time,rect,input={}){if(!(image?.naturalWidth||image?.width))return false;const f={...cutoutWalkDefaults,...input},rig=f.walkRig,ps=parts(image,f),pose=cutoutWalkPose(time,f),[x,y,w,h]=rect;c.save();c.translate(x,y+pose.bob*h/rig.height);c.scale(w/rig.width,h/rig.height);const hip=rig.hip,draw=(name,origin)=>c.drawImage(ps[name],-origin[0],-origin[1]);for(const side of ['back','front']){c.save();c.translate(...hip);c.rotate(pose[side]*Math.PI/180);draw(side+'Thigh',hip);const knee=rig[side+'Knee'];c.translate(knee[0]-hip[0],knee[1]-hip[1]);c.rotate(pose[side+'Knee']*Math.PI/180);draw(side+'Shin',knee);c.restore();}if(f.walkArmsEnabled){ // redraw the body without the original arm pixels, then articulate original artwork.
 const body=ps.body,bc=body.getContext('2d');if(!body._armsRemoved){bc.save();bc.globalCompositeOperation='destination-out';for(const poly of [[[436,245],[535,260],[560,460],[611,690],[627,811],[570,834],[518,775],[451,590],[410,410]],[[610,445],[670,490],[758,596],[845,640],[880,716],[810,730],[704,676],[610,590]]]){bc.beginPath();poly.forEach((p,i)=>i?bc.lineTo(...p):bc.moveTo(...p));bc.closePath();bc.fill();}bc.restore();body._armsRemoved=true;}
 c.save();c.beginPath();c.moveTo(430,280);c.lineTo(530,280);c.lineTo(610,840);c.lineTo(490,840);c.lineTo(405,420);c.closePath();c.clip();c.drawImage(image,330,390,100,510,425,280,180,560);c.restore();c.drawImage(ps.body,0,0);
 // Clear original arms using the cached cut body on subsequent frames; first draw below is covered by arm layers.
 const arm=(name,shoulder,elbow,sgn)=>{const wrist=name==='frontArm'?[f.walkFrontWristX,f.walkFrontWristY]:[f.walkBackWristX,f.walkBackWristY],cut=name==='frontArm'?530:590;c.save();c.translate(...shoulder);c.rotate(sgn*pose.arm*Math.PI/180);c.translate(-shoulder[0],-shoulder[1]);c.save();c.beginPath();c.rect(0,0,1024,cut+10);c.clip();c.drawImage(ps[name],0,0);c.restore();c.translate(...elbow);c.rotate(sgn*pose.elbow*Math.PI/180);c.translate(-elbow[0],-elbow[1]);c.save();c.beginPath();c.rect(0,cut-10,1024,wrist[1]-cut+22);c.clip();c.drawImage(ps[name],0,0);c.restore();c.translate(...wrist);c.rotate(sgn*pose.wrist*Math.PI/180);c.translate(-wrist[0],-wrist[1]);c.beginPath();c.rect(0,wrist[1]-10,1024,1536);c.clip();c.drawImage(ps[name],0,0);c.restore();};arm('backArm',[f.walkBackShoulderX,f.walkBackShoulderY],[f.walkBackElbowX,f.walkBackElbowY],-1);arm('frontArm',[f.walkFrontShoulderX,f.walkFrontShoulderY],[f.walkFrontElbowX,f.walkFrontElbowY],1);
}else c.drawImage(ps.body,0,0);c.restore();const turn=(p,o,d)=>{const a=d*Math.PI/180,x=p[0]-o[0],y=p[1]-o[1];return [o[0]+x*Math.cos(a)-y*Math.sin(a),o[1]+x*Math.sin(a)+y*Math.cos(a)]},tip=f.walkArmsEnabled?turn(turn(turn(rig.flashlight,[f.walkBackWristX,f.walkBackWristY],-pose.wrist),[f.walkBackElbowX,f.walkBackElbowY],-pose.elbow),[f.walkBackShoulderX,f.walkBackShoulderY],-pose.arm):rig.flashlight;return {flashlight:[x+tip[0]/rig.width*w,y+(tip[1]+pose.bob)/rig.height*h],pose};}
